#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "bicg.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize arrays using Halide to mirror the C init_array().
//
// C init_array (PolyBench BiCG):
//   for (i = 0; i < m; i++)
//     p[i] = (DATA_TYPE)(i % m) / m;
//   for (i = 0; i < n; i++)
//     r[i] = (DATA_TYPE)(i % n) / n;
//   for (i = 0; i < n; i++)
//     for (j = 0; j < m; j++)
//       A[i][j] = (DATA_TYPE)(i * (j+1) % n) / n;
//
// Our layout for A is transposed: C A[i][j] -> Halide A(j,i).
static void init_array(int m,
                       int n,
                       Halide::Buffer<num_t, 2> A,  // shape: (m, n) => A(j, i) == A[i][j] in C
                       Halide::Buffer<num_t, 1> r,  // length n
                       Halide::Buffer<num_t, 1> p)  // length m
{
    Var i("i"), j("j");

    Func init_p("init_p");
    Func init_r("init_r");
    Func init_A("init_A");

    // p[i] = (DATA_TYPE)(i % m) / m;
    init_p(i) = cast<num_t>(i % m) / cast<int>(m);

    // r[i] = (DATA_TYPE)(i % n) / n;
    init_r(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = (DATA_TYPE)(i * (j+1) % n) / n;
    // C layout: A[i][j] -> Halide: A(j, i)
    init_A(j, i) = cast<num_t>((i * (j + 1)) % n) / cast<int>(n);

    // ----------------------------------------------------------------------
    // Scheduling for initialization
    //
    // These run only once, but they touch O(m*n) elements; giving them a
    // reasonable schedule improves startup time for large problems.
    // We keep the math identical and just improve locality/parallelism.
    // ----------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // 1D inits: parallel over outer chunks, vectorize inner.
    {
        Var io("io"), ii("ii");

        init_p.compute_root()
              .split(i, io, ii, 1024)
              .vectorize(ii, vec_width)
              .parallel(io);

        init_r.compute_root()
              .split(i, io, ii, 1024)
              .vectorize(ii, vec_width)
              .parallel(io);
    }

    // 2D A init: tile in (j,i), parallelize over tiles, vectorize across j.
    {
        Var jo("jo"), ji("ji"), io("io"), ii("ii");

        init_A.compute_root()
              // tiles of 32x32 generally give good cache behavior
              .tile(j, i, jo, io, ji, ii, 32, 32)
              // inner-most over j for contiguous writes
              .reorder(ji, ii, jo, io)
              .vectorize(ji, vec_width)
              .parallel(jo); // outer tiles in j
    }

    // Materialize into the provided Buffers.
    init_p.realize(p);
    init_r.realize(r);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from bicg.hpp / PolyBench)
    int n = N;  // number of rows of A, and length of r, q
    int m = M;  // number of columns of A, and length of p, s

    // Buffers corresponding to the C arrays.
    //
    // C: DATA_TYPE A[N][M]  -> Halide: Buffer<num_t,2> A(m, n)  with A(j, i) == A[i][j]
    // C: DATA_TYPE s[M]     -> Halide: Buffer<num_t,1> s(m)
    // C: DATA_TYPE q[N]     -> Halide: Buffer<num_t,1> q(n)
    // C: DATA_TYPE p[M]     -> Halide: Buffer<num_t,1> p(m)
    // C: DATA_TYPE r[N]     -> Halide: Buffer<num_t,1> r(n)
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 1> s(m);
    Halide::Buffer<num_t, 1> q(n);
    Halide::Buffer<num_t, 1> p(m);
    Halide::Buffer<num_t, 1> r(n);

    // Initialize data (equivalent to init_array in the C version).
    init_array(m, n, A, r, p);

    // Wrap input arrays in ImageParams for Halide.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");  // (m, n) with A_param(j, i)
    ImageParam p_param(type_of<num_t>(), 1, "p_param");  // (m)
    ImageParam r_param(type_of<num_t>(), 1, "r_param");  // (n)

    A_param.set(A);
    p_param.set(p);
    r_param.set(r);

    // Halide variables.
    Var i("i"), j("j");

    // RDom extents derived from the input buffers (fixed for this problem size).
    RDom ri(0, r.dim(0).extent(), "ri");  // reduction over rows: 0 .. n-1
    RDom rj(0, p.dim(0).extent(), "rj");  // reduction over cols: 0 .. m-1

    // ------------------------------------------------------------------------
    // Halide formulation of the BiCG kernel.
    //
    // Original C kernel:
    //
    // for (i = 0; i < m; i++)
    //   s[i] = 0;
    // for (i = 0; i < n; i++) {
    //   q[i] = 0;
    //   for (j = 0; j < m; j++) {
    //     s[j] = s[j] + r[i] * A[i][j];
    //     q[i] = q[i] + A[i][j] * p[j];
    //   }
    // }
    //
    // Mathematically:
    //   s[j] = sum_{i=0..n-1} r[i] * A[i][j]   (A^T * r)
    //   q[i] = sum_{j=0..m-1} A[i][j] * p[j]   (A * p)
    //
    // Our layout: C A[i][j] -> Halide A_param(j, i)
    // ------------------------------------------------------------------------

    // s[j] = sum_i r[i] * A[i][j]
    // Halide: A[i][j] -> A_param(j, i)
    Func s_func("s");
    s_func(j) = cast<num_t>(0);
    s_func(j) += r_param(ri) * A_param(j, ri);

    // q[i] = sum_j A[i][j] * p[j]
    Func q_func("q");
    q_func(i) = cast<num_t>(0);
    q_func(i) += A_param(rj, i) * p_param(rj);

    // ------------------------------------------------------------------------
    // Scheduling for the BiCG kernel
    //
    // Goal: exploit parallelism and vectorization while preserving the
    // reduction semantics and memory locality.
    //
    // - s_func: reduction over ri (rows), pure var j (columns).
    //   For each j, the contributions r[0..n-1] are accumulated in
    //   increasing ri, exactly matching the C loop order.
    //
    //   We:
    //     * parallelize across chunks of j
    //     * vectorize contiguous j within each chunk
    //     * iterate ri outside the innermost j loop so that loads from
    //       A_param(j, ri) are contiguous in memory for each ri.
    //
    // - q_func: analogous, but reduction over rj (columns), pure var i (rows).
    // ------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Schedule for s_func
    {
        Var sj_outer("sj_outer"), sj_inner("sj_inner");

        // Initialize s in parallel over j.
        s_func.compute_root()
              .parallel(j);

        // Update step: split j into tiles of 64, process tiles in parallel,
        // and vectorize across inner j.
        //
        // Loop structure (conceptual) after scheduling:
        //   for sj_outer:
        //     for ri in 0..n-1:
        //       for sj_inner in 0..tile-1 (vectorized):
        //         j = sj_outer*tile + sj_inner;
        //         s[j] += r[ri] * A(j, ri);
        //
        // For each fixed j, ri still increases from 0..n-1, so the
        // accumulation order for s[j] matches the original code.
        s_func.update()
              .split(j, sj_outer, sj_inner, 64)
              .reorder(sj_inner, ri, sj_outer)
              .vectorize(sj_inner, vec_width)
              .parallel(sj_outer);
    }

    // Schedule for q_func
    {
        Var qi_outer("qi_outer"), qi_inner("qi_inner");

        // Initialize q in parallel over i.
        q_func.compute_root()
              .parallel(i);

        // Update step: analogous to s_func, but over i.
        //
        // Loop structure (conceptual):
        //   for qi_outer:
        //     for rj in 0..m-1:
        //       for qi_inner in 0..tile-1 (vectorized):
        //         i = qi_outer*tile + qi_inner;
        //         q[i] += A(rj, i) * p[rj];
        //
        // For each fixed i, rj increases from 0..m-1, matching the C code.
        q_func.update()
              .split(i, qi_outer, qi_inner, 64)
              .reorder(qi_inner, rj, qi_outer)
              .vectorize(qi_inner, vec_width)
              .parallel(qi_outer);
    }

    // JIT-compile both functions once, so timing measures only execution.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m), newline every 20 elements.
        std::cerr << "s:";
        for (int idx = 0; idx < m; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << s(idx) << ' ';
        }
        std::cerr << "\nq:";

        // Print q (length n), newline every 20 elements.
        for (int idx = 0; idx < n; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << q(idx) << ' ';
        }
        std::cerr << '\n';
    }

    // Print elapsed time in seconds (like gemm.cpp).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
