    // ------------------------------------------------------------------
    // Scheduling for initialization.
    //
    // These run only once, so we keep scheduling simple but still
    // reasonably cache- and vector-friendly:
    //  - Vectorize along the contiguous dimension.
    //  - Parallelize outer loops to use all cores.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // 1D init: parallel over i, vectorize within each chunk.
    init_p.compute_root()
          .vectorize(i, vec_width)
          .parallel(i);

    init_r.compute_root()
          .vectorize(i, vec_width)
          .parallel(i);

    // 2D init for A: tile over (j, i), vectorize across j (contiguous),
    // parallelize tiles across j.
    Var jo("jo"), ji("ji"), io("io"), ii("ii");
    const int tile_j = 64;  // width of a tile in j (contiguous dim)
    const int tile_i = 32;  // height of a tile in i

    init_A
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .vectorize(ji, vec_width)
        .parallel(jo);

    // Realize into the provided Buffers.
    init_p.realize(p);
    init_r.realize(r);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from bicg.hpp / PolyBench)
    int n = N;  // number of rows of A, and length of r, q
    int m = M;  // number of columns of A, and length of p, s

    // Buffers corresponding to the C arrays.
    //
    // C: DATA_TYPE A[N][M]  -> Halide: Buffer<num_t,2> A(m, n)  with A(j, i) == A[i][j]
    // C: DATA_TYPE s[M]     -> Halide: Buffer<num_t,1> s(m)
    // C: DATA_TYPE q[N]     -> Halide: Buffer<num_t,1> q(n)
    // C: DATA_TYPE p[M]     -> Halide: Buffer<num_t,1> p(m)
    // C: DATA_TYPE r[N]     -> Halide: Buffer<num_t,1> r(n)
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 1> s(m);
    Halide::Buffer<num_t, 1> q(n);
    Halide::Buffer<num_t, 1> p(m);
    Halide::Buffer<num_t, 1> r(n);

    // Initialize data (equivalent to init_array in the C version).
    init_array(m, n, A, r, p);

    // Wrap input arrays in ImageParams for Halide.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");  // (m, n)
    ImageParam p_param(type_of<num_t>(), 1, "p_param");  // (m)
    ImageParam r_param(type_of<num_t>(), 1, "r_param");  // (n)

    A_param.set(A);
    p_param.set(p);
    r_param.set(r);

    // Halide variables.
    Var i("i"), j("j");

    // RDom extents derived from the input buffers (fixed for this problem size).
    RDom ri(0, r.dim(0).extent(), "ri");  // 0 .. n-1 (rows of A / entries of r, q)
    RDom rj(0, p.dim(0).extent(), "rj");  // 0 .. m-1 (cols of A / entries of p, s)

    // ------------------------------------------------------------------------
    // Halide formulation of the BiCG kernel.
    //
    // Original C kernel:
    //
    // for (i = 0; i < m; i++)
    //   s[i] = 0;
    // for (i = 0; i < n; i++) {
    //   q[i] = 0;
    //   for (j = 0; j < m; j++) {
    //     s[j] = s[j] + r[i] * A[i][j];
    //     q[i] = q[i] + A[i][j] * p[j];
    //   }
    // }
    //
    // Which is mathematically:
    //   s[j] = sum_{i=0..n-1} r[i] * A[i][j]   (A^T * r)
    //   q[i] = sum_{j=0..m-1} A[i][j] * p[j]   (A * p)
    //
    // Halide layout: A(i,j) in C is stored as A_param(j, i)
    //   A[i][j]  ==  A_param(j, i)
    // ------------------------------------------------------------------------

    // s[j] = sum_i r[i] * A[i][j]
    // Halide: A(i,j) => A_param(j, i)
    Func s_func("s");
    s_func(j) = cast<num_t>(0);
    s_func(j) += r_param(ri) * A_param(j, ri);

    // q[i] = sum_j A[i][j] * p[j]
    Func q_func("q");
    q_func(i) = cast<num_t>(0);
    q_func(i) += A_param(rj, i) * p_param(rj);

    // ------------------------------------------------------------------------
    // Scheduling for the BiCG kernel.
    //
    // Goals:
    //  - Good spatial locality for A, r, p.
    //  - Parallelize across independent output elements (s and q are 1D).
    //  - Vectorize across contiguous dimensions where possible.
    //
    // Remember:
    //   A_param has layout (j, i), with j contiguous in memory.
    //   s(j) accumulates over ri.
    //   q(i) accumulates over rj.
    // ------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_j = 64;  // tuneable tile size for s's output dimension
    const int tile_i = 64;  // tuneable tile size for q's output dimension

    // ---- Schedule for s_func (computes s = A^T * r) ----
    //
    // We:
    //   - Tile the 1D output j into (jo, ji).
    //   - Parallelize across jo (different chunks of s[j]).
    //   - Vectorize across ji (contiguous A_param(j, ri) accesses).
    //
    // Update step loops conceptually:
    //   for jo in parallel:
    //     for ri in 0..n-1:
    //       for ji in vectorized lanes:
    //         j = jo * tile_j + ji;
    //         s[j] += r[ri] * A(j, ri);
    //
    // Each thread owns a disjoint set of j-indices, so there are no races.
    Var jo_s("jo_s"), ji_s("ji_s");

    s_func.compute_root();
    s_func
        .split(j, jo_s, ji_s, tile_j)
        .parallel(jo_s)
        .vectorize(ji_s, vec_width);

    s_func.update()
        .split(j, jo_s, ji_s, tile_j)
        // ji_s innermost (vectorized), ri next, jo_s outermost (parallel)
        .reorder(ji_s, ri, jo_s)
        .parallel(jo_s)
        .vectorize(ji_s, vec_width);

    // ---- Schedule for q_func (computes q = A * p) ----
    //
    // Using the default loop nest for the reduction, we get:
    //   for i:
    //     for rj:
    //       q[i] += A(rj, i) * p[rj];
    //
    // This already walks A along the contiguous j-dimension (rj) in
    // the inner loop. We tile and parallelize over i, and vectorize
    // across the inner ii dimension of i.
    Var io_q("io_q"), ii_q("ii_q");

    q_func.compute_root();
    q_func
        .split(i, io_q, ii_q, tile_i)
        .parallel(io_q)
        .vectorize(ii_q, vec_width);

    q_func.update()
        .split(i, io_q, ii_q, tile_i)
        // ii_q innermost (vectorized), rj next, io_q outermost (parallel)
        .reorder(ii_q, rj, io_q)
        .parallel(io_q)
        .vectorize(ii_q, vec_width);

    // JIT-compile both functions once so timing measures only execution.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m), newline every 20 elements.
        std::cerr << "s:";
        for (int idx = 0; idx < m; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << s(idx) << ' ';
        }
        std::cerr << "\nq:";

        // Print q (length n), newline every 20 elements.
        for (int idx = 0; idx < n; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << q(idx) << ' ';
        }
        std::cerr << '\n';
    }

    // Print elapsed time in seconds (like gemm.cpp).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
