    s_func
        .compute_root()
        .split(j, s_jo, s_ji, s_j_tile)
        .parallel(s_jo)
        .vectorize(s_ji, vec_width);

    // Update definition: s(j) += r[ri] * A(j, ri)
    // Reorder so that the inner loop is over s_ji (vectorized j),
    // then ri, then outer tiles s_jo:
    s_func.update()
        .split(j, s_jo, s_ji, s_j_tile)
        .reorder(s_ji, ri, s_jo)
        .parallel(s_jo)
        .vectorize(s_ji, vec_width);

    // ---- Schedule for q_func ------------------------------------------------
    // Parallelize across i (rows of A); for each i, iterate rj (columns)
    // in the inner loop and vectorize across rj to get contiguous loads.
    Var q_io("q_io"), q_ii("q_ii");
    const int q_i_tile = 128;  // tile size in i

    // Pure definition: initialize q(i) = 0
    q_func
        .compute_root()
        .split(i, q_io, q_ii, q_i_tile)
        .parallel(q_io);

    // Update: q(i) += A(rj, i) * p[rj]
    // Reorder so that the inner loop is rj (for vectorization),
    // then the inner i-tile coordinate, then the outer i-tile:
    q_func.update()
        .split(i, q_io, q_ii, q_i_tile)
        .reorder(rj, q_ii, q_io)
        .parallel(q_io)
        .vectorize(rj, vec_width);

    // JIT-compile both functions once, targeting the chosen architecture.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m), newline every 20 elements.
        std::cerr << "s:";
        for (int idx = 0; idx < m; idx++) {
            if (idx % 20 == 0) {
